function validate([releaseTimes, keysPressed]) {
  const n = releaseTimes.length;
  if (n < 2 || n > 1000) return 'There must be 2 to 1000 key presses.';
  if (keysPressed.length !== n) return 'keysPressed must have one letter per release time.';
  if (!/^[a-z]+$/.test(keysPressed)) return 'keysPressed may contain only lowercase letters.';
  for (let i = 0; i < n; i++) {
    if (!Number.isInteger(releaseTimes[i]) || releaseTimes[i] < 1 || releaseTimes[i] > 1e9) return 'Each release time is a whole number from 1 to 10^9.';
    if (i > 0 && releaseTimes[i] <= releaseTimes[i - 1]) return 'Release times must strictly increase.';
  }
  return null;
}

