function slowestKey(releaseTimes, keysPressed) {
  let bestKey = keysPressed[0];
  let bestDuration = releaseTimes[0];

  for (let i = 1; i < releaseTimes.length; i++) {
    const duration = releaseTimes[i] - releaseTimes[i - 1];
    const key = keysPressed[i];
    if (duration > bestDuration || (duration === bestDuration && key > bestKey)) {
      bestDuration = duration;
      bestKey = key;
    }
  }
  return bestKey;
}

