function slowestKey(releaseTimes, keysPressed) {
  const durations = releaseTimes.map((time, i) => (i === 0 ? time : time - releaseTimes[i - 1]));
  const longest = Math.max(...durations);
  const keys = [];
  for (let i = 0; i < durations.length; i++) if (durations[i] === longest) keys.push(keysPressed[i]);
  keys.sort();
  return keys[keys.length - 1];
}

