function generate(rand, size) {
  const n = size === 'large' ? 1000 : 2 + Math.floor(rand() * 7);
  const letters = size === 'large' ? 26 : 1 + Math.floor(rand() * 5);
  const step = size === 'large' ? (rand() < 0.5 ? 1000000 : 20) : 4;
  const releaseTimes = [];
  let keysPressed = '';
  let time = 0;
  for (let i = 0; i < n; i++) {
    time += 1 + Math.floor(rand() * step);
    releaseTimes.push(time);
    keysPressed += String.fromCharCode(97 + Math.floor(rand() * letters));
  }
  return [releaseTimes, keysPressed];
}
